#include <stdio.h>

int is_balanced(const char *s) {
    char stack[100];
    int top = -1;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top < 0) {
                return 0;
            }
            char open = stack[top--];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return 0;
            }
        }
    }
    return top == -1;
}

int main() {
    printf("%d\n", is_balanced("()[]"));
    printf("%d\n", is_balanced("((("));
    return 0;
}
